     1→# ABOUTME: Test for use-def chains in Sea of Nodes IR
     2→# ABOUTME: Validates that nodes track which other nodes use their output (use-def chains)
     3→
     4→use v5.42;
     5→use Test::More;
     6→use Test::Deep;
     7→
     8→use_ok('Chalk::IR::Node');
     9→use_ok('Chalk::IR::Graph');
    10→
    11→# Test that nodes can track their uses
    12→subtest 'Node tracks uses via Graph' => sub {
    13→    my $graph = Chalk::IR::Graph->new();
    14→
    15→    # Create Start node
    16→    my $start = Chalk::IR::Node->new(
    17→        id => 'node_0',
    18→        op => 'Start',
    19→        inputs => [],
    20→        attributes => { function => 'main' }
    21→    );
    22→    $graph->add_node($start);
    23→
    24→    # Create Constant node that depends on Start
    25→    my $constant = Chalk::IR::Node->new(
    26→        id => 'node_1',
    27→        op => 'Constant',
    28→        inputs => ['node_0'],  # Uses Start
    29→        attributes => { value => 42, type => 'Int' }
    30→    );
    31→    $graph->add_node($constant);
    32→
    33→    # Create Return node that depends on both Start and Constant
    34→    my $return = Chalk::IR::Node->new(
    35→        id => 'node_2',
    36→        op => 'Return',
    37→        inputs => ['node_0', 'node_1'],  # Uses Start and Constant
    38→        attributes => {}
    39→    );
    40→    $graph->add_node($return);
    41→
    42→    # Test: Get uses of Start node (should be used by Constant and Return)
    43→    my $start_uses = $graph->get_uses('node_0');
    44→    ok($start_uses, 'get_uses returns a value for Start node');
    45→    is(ref($start_uses), 'ARRAY', 'get_uses returns an array ref');
    46→    cmp_bag($start_uses, ['node_1', 'node_2'],
    47→            'Start node is used by Constant and Return');
    48→
    49→    # Test: Get uses of Constant node (should be used by Return)
    50→    my $const_uses = $graph->get_uses('node_1');
    51→    ok($const_uses, 'get_uses returns a value for Constant node');
    52→    is(ref($const_uses), 'ARRAY', 'get_uses returns an array ref');
    53→    cmp_deeply($const_uses, ['node_2'],
    54→               'Constant node is used by Return');
    55→
    56→    # Test: Get uses of Return node (should have no uses)
    57→    my $return_uses = $graph->get_uses('node_2');
    58→    ok(defined($return_uses), 'get_uses returns a value for Return node');
    59→    is(ref($return_uses), 'ARRAY', 'get_uses returns an array ref');
    60→    cmp_deeply($return_uses, [],
    61→               'Return node has no uses');
